init.source:
function () {
            _super.prototype.execute.call(this);
            var encoders = [];
            if (this._historyModel.getIsHistoryReplay() && !this._server.getInitResponse()) {
                encoders.push(new sgigame.HistoryReplayEncoder(this._historyModel.getNextState()));
                this._historyModel.restart();
            }
            if (this._platformModel.promoInfo != undefined) {
                this._server.getGLSInitResquester().setPromoInfo(this._platformModel.promoInfo);
            }
            var initData = new server.GLSRequest(encoders);
            this._server.makeInitRequest(initData);
        }

logic.source:
function () {
            _super.prototype.execute.call(this);
            if (this._subGamesModel.isLogicRequestSent) {
                return;
            }
            this._subGamesModel.isLogicRequestSent = true;
            var encoders = [
                this.getStakeEncode(),
                new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
            ];
            if (this._statesModel.getCurrentState().stateName !== sgigame.PreGameStates.RECOVERY_INIT_STATE) {
                var history = this._historyModel.getNextState();
                if (history) {
                    encoders.push(new sgigame.HistoryReplayEncoder(history));
                }
            }
            if (this._forceModel.forceSet) {
                var forceEncoder = new sgigame.ForceEncoder(this._forceModel.reelData ? this._forceModel.reelData.positions : [0, 0, 0, 0, 0], this._forceModel.reelData ? this._forceModel.reelData.index : 0);
                encoders.push(forceEncoder);
            }
            this._forceModel.forceSet = false;
            if (!sgigame.GameConfig.isFreeSpin) {
                this._commonUIData.startPlay();
            }
            sgigame.GameConfig.isFreeSpin = false;
            var data = new server.GLSRequest(encoders);
            this._server.makeLogicRequest(data);
        }

end.source:
function () {
            _super.prototype.execute.call(this);
            if (!this._historyModel.getIsHistoryReplay()) {
                this._server.makeEndRequest(new server.GLSRequest([]));
                sgigame.GameConfig.isFreeSpin = false;
            }
        }

