money.source:
function (input, object) {
            if (input.getElementsByTagName("GameWinInfo") && input.getElementsByTagName("GameWinInfo").length > 0) {
                var node = input.getElementsByTagName("GameWinInfo")[0];
                var gameWinInfoData = new sgigame.GameWinInfoData;
                gameWinInfoData.totalWagerWin = parseInt(this.getAttributeFromNode(node, "totalWagerWin", "number"));
                gameWinInfoData.totalBaseGameWin = parseInt(this.getAttributeFromNode(node, "totalBaseGameWin", "number"));
                gameWinInfoData.totalFreeSpinsWin = parseInt(this.getAttributeFromNode(node, "totalFreeSpinsWin", "number"));
                gameWinInfoData.maxWinValue = parseInt(this.getAttributeFromNode(node, "maxWinValue", "number"));
                gameWinInfoData.isMaxWin = this.getAttributeFromNode(node, "isMaxWin", "string") == "Y" ? true : false;
                object.gameWinInfoData = gameWinInfoData;
            }
        }

free.source:
function (input, object) {
            if (input.getElementsByTagName("BGInfo") && input.getElementsByTagName("BGInfo").length > 0) {
                var node = input.getElementsByTagName("BGInfo")[0];
                var freeSpinBGInfoData = new sgigame.BGInfoData;
                freeSpinBGInfoData.freeSpinWheelIndex = parseInt(this.getAttributeFromNode(node, "freeSpinWheelIndex", "number"));
                freeSpinBGInfoData.totalFreeSpinsTriggered = parseInt(this.getAttributeFromNode(node, "totalFreeSpinsTriggered", "number"));
                freeSpinBGInfoData.freeSpinTriggerWin = parseInt(this.getAttributeFromNode(node, "freeSpinTriggerWin", "number"));
                object.freeSpinBGInfoData = freeSpinBGInfoData;
            }
            if (input.getElementsByTagName("FSInfo") && input.getElementsByTagName("FSInfo").length > 0) {
                var node = input.getElementsByTagName("FSInfo")[0];
                var freeSpinFSInfoData = new sgigame.FSInfoData;
                freeSpinFSInfoData.totalFreeSpinsWin = parseInt(this.getAttributeFromNode(node, "totalFreeSpinsWin", "number"));
                freeSpinFSInfoData.remainingFreeSpins = parseInt(this.getAttributeFromNode(node, "remainingFreeSpins", "number"));
                freeSpinFSInfoData.retriggeredFsRemaining = parseInt(this.getAttributeFromNode(node, "retriggeredFsRemaining", "number"));
                freeSpinFSInfoData.numTotalFreeSpins = parseInt(this.getAttributeFromNode(node, "numTotalFreeSpins", "number"));
                freeSpinFSInfoData.freeSpinMultiplierIndex = parseInt(this.getAttributeFromNode(node, "freeSpinMultiplierIndex", "number"));
                freeSpinFSInfoData.freeSpinTriggerWin = parseInt(this.getAttributeFromNode(node, "freeSpinTriggerWin", "number"));
                freeSpinFSInfoData.lastFreeSpin = this.getAttributeFromNode(node, "lastFreeSpin", "string") == "Y" ? true : false;
                freeSpinFSInfoData.isFsRetriggered = this.getAttributeFromNode(node, "isFsRetriggered", "string") == "Y" ? true : false;
                freeSpinFSInfoData.isInRetrigger = this.getAttributeFromNode(node, "isInRetrigger", "string") == "Y" ? true : false;
                if (freeSpinFSInfoData.isFsRetriggered) {
                    freeSpinFSInfoData.freeSpinWheelIndex = parseInt(this.getAttributeFromNode(node, "freeSpinWheelIndex", "number"));
                }
                else {
                    freeSpinFSInfoData.freeSpinWheelIndex = null;
                }
                freeSpinFSInfoData.isBonusGuarantee = this.getAttributeFromNode(node, "isBonusGuarantee", "string") == "Y" ? true : false;
                freeSpinFSInfoData.bonusGuarantee = parseInt(this.getAttributeFromNode(node, "bonusGuarantee", "number"));
                object.freeSpinFSInfoData = freeSpinFSInfoData;
            }
        }

attr.source:
function (dataNode, attribute, returnType) {
            if (returnType === void 0) { returnType = "string"; }
            var attributeValue = "";
            if (returnType == "number")
                attributeValue = "-1";
            if (dataNode.attributes.getNamedItem(attribute)) {
                attributeValue = dataNode.attributes.getNamedItem(attribute).value;
            }
            return attributeValue;
        }

next.source:
function () {
            var _this = this;
            _super.prototype.execute.call(this);
            if (!this._statesModel.isFreeSpin) {
                return;
            }
            var logicResponse = this._server.getLogicResponse();
            var remainingFS = logicResponse.freeSpinFSInfoData.remainingFreeSpins;
            var totalFS = logicResponse.freeSpinFSInfoData.numTotalFreeSpins;
            if (!this._forceModel.forceOpen && !logicResponse.reelSpinData[0].bonusAwarded && (this._subGamesModel.isFsWinCycleComp && this._subGamesModel.isFsBangUpComp && (this._subGamesModel.isBigWinAnimFinish == undefined || this._subGamesModel.isBigWinAnimFinish))) {
                if (!logicResponse.gameWinInfoData.isMaxWin) {
                    if (remainingFS > 0) {
                        if (this._statesModel.getCurrentState().stateName == sgigame.BonusGameState.FREE_GAME_RESULT) {
                            this._subGamesModel.isFsWinCycleComp = this._subGamesModel.isFsBangUpComp = false;
                            this._subGamesModel.isFreeSpinsComplete = false;
                            TweenLite.delayedCall(0.5, function () {
                                _this._statesModel.changeStateByName(sgigame.BonusGameState.FREE_GAME_LOGIC_REQUEST);
                            });
                        }
                    }
                    else {
                        this._subGamesModel.isFsWinCycleComp = this._subGamesModel.isFsBangUpComp = false;
                        this._subGamesModel.isFreeSpinsComplete = true;
                        TweenLite.delayedCall(0.5, function () {
                            _this._statesModel.gotoNextState();
                        });
                    }
                }
            }
        }

headerConstructor.source:
function GLSHeader(metadata, sessionData, glsServerSessionId, gameId, gameVersion) {
            this.GLSID_CASINARENA = "4";
            this.GLSID_FREEPLAY = "65535";
            this.affiliate = sessionData.getContextID();
            this.freePlay = !metadata.isRealMoney();
            this.gameCodeRGI = metadata.getGameCode();
            this.gameId = gameId;
            this.glsId = (this.freePlay ? this.GLSID_FREEPLAY : this.GLSID_CASINARENA);
            this.langCode = metadata.getLocale();
            this.sessionId = glsServerSessionId;
            this.userId = sessionData.getPlayerID();
            this.version = gameVersion;
            this.promotions = false;
            this.channel = "I";
            this.userType = "C";
            this.currencyCode = "";
        }

